105	// GitHubRelease represents a GitHub release.
106	type GitHubRelease struct {
107		TagName     string    `json:"tag_name"`
108		Name        string    `json:"name"`
109		Body        string    `json:"body"` // Release notes (markdown)
110		PublishedAt time.Time `json:"published_at"`
