151	func loadCachedVersion(path string) (*cachedVersion, error) {
152		data, err := safefs.ReadFile(path)
153		if err != nil {
154			return nil, err
155		}
156		var cv cachedVersion
157		if err := json.Unmarshal(data, &cv); err != nil {
158			return nil, err
159		}
160		return &cv, nil
161	}
